globalThis.scoopWaterBlock = async function (pos) {
  const block = bot.blockAt(pos)
  if (!block || (block.name !== 'water' && block.name !== 'flowing_water')) {
    return false
  }
  await bot.equip(mcData.itemsByName.bucket.id, 'hand')
