    for (const p of obsBlocks) {
      if (lib.count('obsidian') >= targetCount || isCancelled()) break
      await bot.equip(mcData.itemsByName.diamond_pickaxe.id, 'hand')
      await lib.dig(p.x, p.y, p.z)
      await lib.pickup(4)
    }
  }
  return lib.count('obsidian')
}

